---@class TeamMember
---我方角色数据对象
local TeamMember = {}
function TeamMember.New(data, id, wave)
    ---@type TeamMember
    local this = {}
    setmetatable(this, { __index = TeamMember })
    this.playerId = checkInt(data.playerId)
    this.id = checkNumber(id)
    this.cardId = checkNumber(data.cardId)
    this.enemyId = checkNumber(data.enemyId or data.cardId) -- 迷宫 字段名 cardId, 其他关卡 enemyId
    this.playerCardId = checkNumber(data.playerCardId)
    this.skinId = checkNumber(data.skinId)
    this.level = checkNumber(data.level)
    this.enemyType = checkNumber(data.type)
    this.attrType = checkNumber(data.attribute)
    this.career = checkNumber(data.career)
    this.wave = checkNumber(wave)
    this.aliveState = true
    this.enterVoice = data.enterVoice
    this.weaponUnlocked = data.weaponUnlocked
    this.star = checkNumber(data.star)
    this.advanceLevel = math.max(checkNumber(data.advanceLevel), 1)         -- 进阶等级
    this.awakeningLevel = math.max(checkNumber(data.awakeningLevel), 1)     -- 被动技能等级
    --- 技能列表
    this.skillList = { }
    for i, v in pairs(data.generalSkills) do
        this.skillList[checkString(i)] = { skillId = v, skillLv = 1 }
    end
    local finalSkill = string.split(data.finalSkills, "=")[1]
    local finalSkill_lv = string.split(data.finalSkills, "=")[2]
    this.skillList["0"] = { skillId = checkInt(finalSkill), skillLv = checkInt(finalSkill_lv) }
    --- 人物信息
    local cAttr = UIBattlingTools.FillCharactorMapAttr(data.attr)
    this.mapAttr = cAttr
    this.hpPreInBattleStart = checkNumber(data.currentHp and data.currentHp / cAttr[Constants.AttrTypeId.Hp] or 1)
    this.spInBattleStart = checkNumber(IsNull(data.currentEnergy) and 0 or data.currentEnergy)
    this.spMax = checkNumber(data.maxSP or 6)
    --- 被动技能
    local strPassiveSkill = data.passiveSkills
    if not isNull(strPassiveSkill) then
        local tPSList = string.split(strPassiveSkill, "&")
        this.passiveSkillsList = {}
        for i, skill in ipairs(tPSList) do
            local skillId = checkInt(string.split(skill, "=")[1])
            local skillLv = checkInt(string.split(skill, "=")[2])       
            table.insert(this.passiveSkillsList, { skillId = skillId, skillLv = skillLv })
        end
    end
    return this
end

---@class SkillData
---技能数据对象
local SkillData = {}
function SkillData.New(skillId, skillLv)
    ---@type SkillData
    local this = {}
    setmetatable(this, { __index = SkillData })
    this.skillId = skillId
    this.skillLv = skillLv
    return this
end

