---InitBattlingData
---初始化 战中Data
---@param data table
function UIBattlingDataMgr:InitBattlingData(data)
    local clone = clone(data)
    self.battlingData = clone
    --- resetTeam
    self.playerTeam = nil
    self.playerTeam = {}
    self.enemyTeam = nil
    self.enemyTeam = {}
    self:FillPlayerTeamInfo(self.battlingData.playerTeam)
    self:FillEnemyTeamInfo(self.battlingData.enemyTeam)
    self.battleRoundsMax = self.battlingData.rounds
    --- 获取当前 关卡Id
    self.questId = data.questId
end

---FillPlayerTeamInfo
---填充玩家小队成员队员信息
---@param playerTeamData table
function UIBattlingDataMgr:FillPlayerTeamInfo(playerTeamData)
    for i = 1, #playerTeamData do
        for j = 1, #playerTeamData[i] do
            local characterData = playerTeamData[i][j]
            local wave = i
            self:SetPlayerTeamData(characterData, nil, wave)
        end
    end
end

---FillEnemyTeamInfo
---填充敌方小队成员队员信息
---@param enemyTeamData table
function UIBattlingDataMgr:FillEnemyTeamInfo(enemyTeamData)
    if IsNull(self.battleWave) then
        self.battleWave = {}
    end
    for i = 1, #enemyTeamData do
        local waveType = 1 -- 默认无 Boss 波次
        for j = 1, #enemyTeamData[i] do
            local wave = i
            local enemyData = self:SetEnemyTeamData(enemyTeamData[i][j], nil, wave)
            waveType = (enemyData.enemyType) == 2 and 2 or 1
            self:FillEleBreakMonsterId(enemyData.id, enemyTeamData[i][j].weakId)
        end
        table.insert(self.battleWave, waveType)
    end
end

---SetPlayerTeamData
---设置我方角色信息
---@param data table
---@param wave number
function UIBattlingDataMgr:SetPlayerTeamData(data, bfId, wave)
    local id = bfId ~= nil and bfId or data.id
    local playerData = TeamMember.New(data, id, wave)
    self:InsertCharacter(playerData)
    return playerData
end

---SetEnemyTeamData
---设置敌方角色信息
---@param data table
---@param bfId number 战场ID
---@param wave number 波次信息
function UIBattlingDataMgr:SetEnemyTeamData(data, bfId, wave)
    local id = bfId ~= nil and bfId or data.id
    local npcId = data.enemyId or data.cardId --- 索引ID
    local enemyData = TeamMember.New(data, id, wave)
    self:InsertEnemy(enemyData)
    return enemyData
end

--- 设置阵营角色数据
---@param camp any
---@param data any
---@param bfId any
---@param wave any
function UIBattlingDataMgr:SetTeamData(camp, data, bfId, wave)
    if camp == Constants.Camp.One then
        return self:SetPlayerTeamData(data, bfId, wave)
    else
        return self:SetEnemyTeamData(data, bfId, wave)
    end
end

---FillBossInfoMap
---填充当局对战 Boss 信息列表
---@param id integer @ battleFieldId
---@param monsterId integer @ monsterId
function UIBattlingDataMgr:FillEleBreakMonsterId(id, weaknessId)
    if isNull(self.listMonsterHaveEleBreak) then
        self.listMonsterHaveEleBreak = {}
    end
    if not Tools.isNullKey(weaknessId) then
        table.insert(self.listMonsterHaveEleBreak, { uid = id, effectId = weaknessId })
    end
end

