---GetPlayerTeamList
---获取本局玩家队伍信息
---@return table @ playerTeamData
function UIBattlingDataMgr:GetPlayerTeamList(wave)
    local teamData
    if wave then
        teamData = {}
        for i, v in ipairs(self.playerTeam) do
            if v.wave == wave then
                table.insert(teamData, v)
            end
        end
    else
        teamData = self.playerTeam
    end
    return teamData
end

