---GetCharactorDataById
---通过战局 Id 获取角色数据信息
---@param id integer
---@return table
function UIBattlingDataMgr:GetCharactorDataById(id)
    if isNull(self.enemyTeam) or isNull(self.playerTeam) then return end
    for i = 1, #self.enemyTeam do
        if self.enemyTeam[i].id == id then
            return self.enemyTeam[i]
        end
    end
    for i = 1, #self.playerTeam do
        if self.playerTeam[i].id == id then
            return self.playerTeam[i]
        end
    end
end

