--- 获取猫球主动技能id
---@param id any
function UIBattlingDataMgr:GetCatFinalSkillData(id)
    for i, v in ipairs(self.playerTeamCat) do
        if v.id == id then
            local fsData = string.split(v.fs, "=")
            local data = {
                skillId = fsData[1],
                skillLv = fsData[2],
            }
            return data
        end
    end
    for i, v in ipairs(self.enemyTeamCat) do
        if v.id == id then
            local fsData = string.split(v.fs, "=")
            local data = {
                skillId = fsData[1],
                skillLv = fsData[2],
            }
            return data
        end
    end
    return
end

