---InsertCharacter
---检测 玩家队伍人物 数据是重复
---@param data table
---@param id integer
function UIBattlingDataMgr:InsertCharacter(data, id)
    if id then data.id = id end
    for i = 1, #self.playerTeam do
        if data.id == self.playerTeam[i].id then return end
    end
    table.insert(self.playerTeam, data)
end

---InsertEnemy
---检测 敌方队伍人物 数据是重复
---@param data table
function UIBattlingDataMgr:InsertEnemy(data)
    local characterUID = data.id -- 角色战场 Id
    for i = 1, #self.enemyTeam do
        if characterUID == self.enemyTeam[i].id then
            return
        end
    end
    table.insert(self.enemyTeam, data)
end

