---GetRoleDataByRoleId
---通过角色 ID 获取角色信息
---@param roleId integer @ 角色ID
function UIBattlingDataMgr:GetRoleDataByRoleId(roleId)
    for i = 1, #self.playerTeam do
        local roleData = self.playerTeam[i]
        local roleIdInData = roleData.id
        if roleIdInData == roleId then
            return roleData
        end
    end
    for i = 1, #self.enemyTeam do
        local roleData = self.enemyTeam[i]
        local roleIdInData = roleData.id
        if roleIdInData == roleId then
            return roleData
        end
    end
end

