function UIBattlingDataMgr:GetSkillIdByRoleIdAndSkillIndex(roleId, skillIndex)
    local roleData = self:GetRoleDataByRoleId(roleId)
    if roleData then
        return roleData.skillList[tostring(skillIndex)]
