---GetBattleTipsValue
---获取当前关卡当前波次的 TipsId
---@param questId integer @ 关卡 Id
---@param wave integer @ 当前波次
function UIBattlingDataMgr:GetBattleTipsValue(questId, wave)
    if isNull(questId) or isNull(wave) then return -1 end
    local refId = string.format("%d_%d",questId,wave)
    local levelData = Core:GetLevelData( questId )
    if isNull(levelData) then return -1 end
    local waveData = levelData[wave]
    return isNull(waveData) and -1 or waveData.tips
end

