function UIBattlingDataMgr:GetBossHPMultiNum(questId, wave)
    if isNull(questId) or isNull(wave) then return -1 end
    local refId = string.format("%d_%d",questId,wave)
    local levelData = Core:GetLevelData( questId )
    if isNull(levelData) then return -1 end
    local waveData = levelData[wave]
    return isNull(waveData) and 1 or waveData.hpCount
end

function UIBattlingDataMgr:GetSkillCardRoleIdWithIndexId(skillCardId)
    for i = 1, #self.playerTeam do
        local roleData = self.playerTeam[i]
        local roleId = roleData.id
        local skillList = roleData.skillList
        for j, skillData in pairs(skillList) do
            local skillId = skillData.skillId
            if skillCardId == skillId then
                return roleId, j
            end
        end
    end
    for i = 1, #self.enemyTeam do
        local roleData = self.enemyTeam[i]
        local roleId = roleData.id
        local skillList = roleData.skillList
        for j, skillData in pairs(skillList) do
            local skillId = skillData.skillId
            if skillCardId == skillId then
                return roleId, j
            end
        end
    end
    return nil, nil
end

--------------------------------------SetData

function UIBattlingDataMgr:GetDamageTypeData(damageTypeId)
    local data = self.dicDataDamageType[damageTypeId]
    if not data then
        local setting = SettingMgr:GetInstance():GetSetting(AutoIds.IdSetting276, "DamageTypeVo")
        --@RefType [Game.Setting.Vo.DamageTypeVo#DamageTypeVo]
        data = setting:Get(damageTypeId)
        self.dicDataDamageType[damageTypeId] = data
    end
    return data
end

function UIBattlingDataMgr:GetSkillIsUltra(skillIndex, roleId)
    skillIndex = checkNumber(skillIndex)
    roleId = checkNumber(roleId)
    local roleView = BattleViewMgr:FindRoleView(roleId)
    if isNull(roleView) then return false end
    local skillShowId = checkNumber(roleView:GetSkillShowId(skillIndex))
    local skillViewVo = checkTable(UIBattlingTools.GetSkillViewVo(skillShowId))
    if isNull(skillViewVo) then return false end
    local isUltra = skillViewVo.skillShowType == Constants.SkillShowType.Ultra
            or skillViewVo.skillShowType == Constants.SkillShowType.TimelineUltra
    return checkBool(isUltra)
end

--- 添加猫球
---@param skillCatData any
function UIBattlingDataMgr:AddSkillCat(skillCatData)
    if skillCatData.c == Constants.Camp.One then
        table.insert(self.playerTeamCat, skillCatData)
    else
        table.insert(self.enemyTeamCat, skillCatData)
    end
end

--- 检查是否有天气提示
function UIBattlingDataMgr:HasWeatherTips()
    local weatherId = BattleViewMgr.initData.climateId
    if isNull(weatherId) then return false end
    return checkNumber(weatherId) > 0
end

--- 获取天气提示icon路径
function UIBattlingDataMgr:GetWeatherTipsIconPath()
    local weatherId = checkNumber(BattleViewMgr.initData.climateId)
    local iconPath = Constants.WeatherTipsIcon[weatherId]
    return iconPath
end

--- 获取天气提示描述
function UIBattlingDataMgr:GetWeatherTipsDesc()
    local tipsId = self:GetWeatherTipsId()
    local desc = self:GetBattleTipsData(tipsId)
    return (tipsId == 0) and {''} or {desc}
end

--- 获取天气提示id
function UIBattlingDataMgr:GetWeatherTipsId()
    local weatherId = checkNumber(BattleViewMgr.initData.climateId)
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting6222, "WorldBossWeatherVo", weatherId)
    if isNull(vo) then
        return 0
    end
    local tipsId = vo.combatTips
    return tipsId
end

return UIBattlingDataMgr
